import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n, k, d = map(int, data)
    MOD = 1000000007

    def count_ways(target_n, max_edge):
        dp = [0] * (target_n + 1)
        dp[0] = 1
        for i in range(1, target_n + 1):
            for w in range(1, min(i, max_edge) + 1):
                dp[i] = (dp[i] + dp[i - w]) % MOD
        return dp[target_n]

    total = count_ways(n, k)
    without_d = count_ways(n, d - 1)
    ans = (total - without_d) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
